# Generated by test-lab — blind adversarial evaluation
"""Hack source-bearing Dogpile research gate tests for #1114."""

from __future__ import annotations

import json
import sys
from pathlib import Path

import pytest
from typer.testing import CliRunner

SKILLS_DIR = Path(__file__).resolve().parents[2]
if str(SKILLS_DIR) not in sys.path:
    sys.path.insert(0, str(SKILLS_DIR))

import hack.commands as hack_commands  # noqa: E402
from hack.hack import app  # noqa: E402


def _fake_skill(tmp_path: Path) -> Path:
    script = tmp_path / "dogpile-run.sh"
    script.write_text("#!/usr/bin/env bash\nexit 0\n")
    script.chmod(0o755)
    return script


def test_hack_research_invokes_dogpile_packet_mode_without_model(monkeypatch: pytest.MonkeyPatch, tmp_path: Path) -> None:
    skill_script = _fake_skill(tmp_path)
    commands: list[list[str]] = []

    def fake_run(cmd, **_kwargs):
        commands.append(list(cmd))
        output_dir = Path(cmd[cmd.index("--output-dir") + 1])
        output_dir.mkdir(parents=True, exist_ok=True)
        (output_dir / "dogpile-security-packet.json").write_text(
            json.dumps({"schema": "dogpile.security_research_packet.v1", "source_bearing_evidence_count": 1})
        )
        (output_dir / "hack-scan-request.json").write_text("{}\n")

        class Result:
            returncode = 0
            stdout = "packet ready"
            stderr = ""

        return Result()

    monkeypatch.setitem(hack_commands.SKILL_MAP, "dogpile", str(skill_script))
    monkeypatch.setattr(hack_commands.subprocess, "run", fake_run)
    result = CliRunner().invoke(
        app,
        ["research", "fixture vuln", "--skill", "dogpile", "--silent", "--output-dir", str(tmp_path / "packet")],
    )

    assert result.exit_code == 0, result.output
    assert commands
    assert "--model" not in commands[0]
    assert "--no-interactive" in commands[0]
    assert "--output-dir" in commands[0]
    assert "--security-packet-out" in commands[0]


